        return 'China'
    if c in ['United States', 'United States of America', 'USA']:
        return 'USA'
    if c in ['Republic of Korea', 'Korea', 'South Korea']:
        return 'South Korea'
    if c in ['UK', 'United Kingdom']:
        return 'UK'
    if 'Electronic address' in c or len(c) > 40 or c.startswith('China ') or c.startswith('USA ') or c.startswith('United States '):
        return 'Unknown'
    return c

